class Solution:
    def isThereAPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        total = m + n - 1
        if total % 2:
            return False
        target = total // 2
        def dfs(i, j, ones):
            ones += grid[i][j]
            if i == m - 1 and j == n - 1:
                return ones == target
            res = False
            if i + 1 < m:
                res = dfs(i + 1, j, ones)
            if not res and j + 1 < n:
                res = dfs(i, j + 1, ones)
            return res
        return dfs(0, 0, 0)

