class Solution {
    int m, n, target;
    public boolean isThereAPath(int[][] grid) {
        m = grid.length; n = grid[0].length;
        int total = m + n - 1;
        if (total % 2 != 0) return false;
        target = total / 2;
        return dfs(grid, 0, 0, 0);
    }
    private boolean dfs(int[][] g, int i, int j, int ones) {
        ones += g[i][j];
        if (i == m - 1 && j == n - 1) return ones == target;
        boolean res = false;
        if (i + 1 < m) res = dfs(g, i + 1, j, ones);
        if (!res && j + 1 < n) res = dfs(g, i, j + 1, ones);
        return res;
    }
}

