class Solution:
    def isThereAPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        total = m + n - 1
        if total % 2:
            return False
        B = m + n
        dp = [[[False] * (2 * B) for _ in range(n)] for _ in range(m)]
        start = B + (1 if grid[0][0] else -1)
        dp[0][0][start] = True
        for i in range(m):
            for j in range(n):
                d = 1 if grid[i][j] else -1
                for b in range(2 * B):
                    if not dp[i][j][b]:
                        continue
                    if i + 1 < m:
                        dp[i + 1][j][b + d] = True
                    if j + 1 < n:
                        dp[i][j + 1][b + d] = True
        return dp[m - 1][n - 1][B]

