class Solution {
public:
    bool isThereAPath(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int total = m + n - 1;
        if (total % 2) return false;
        int B = m + n;
        vector<vector<vector<char>>> dp(m,
            vector<vector<char>>(n, vector<char>(2 * B, 0)));
        dp[0][0][B + (grid[0][0] ? 1 : -1)] = 1;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                for (int b = 0; b < 2 * B; ++b) {
                    if (!dp[i][j][b]) continue;
                    int d = grid[i][j] ? 1 : -1;
                    if (i + 1 < m) dp[i + 1][j][b + d] = 1;
                    if (j + 1 < n) dp[i][j + 1][b + d] = 1;
                }
        return dp[m - 1][n - 1][B];
    }
};

