    public boolean isThereAPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int total = m + n - 1;
        if (total % 2 != 0) return false;
        int B = m + n;
        boolean[][][] dp = new boolean[m][n][2 * B];
        dp[0][0][B + (grid[0][0] == 1 ? 1 : -1)] = true;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                for (int b = 0; b < 2 * B; b++) {
                    if (!dp[i][j][b]) continue;
                    int d = grid[i][j] == 1 ? 1 : -1;
                    if (i + 1 < m) dp[i + 1][j][b + d] = true;
                    if (j + 1 < n) dp[i][j + 1][b + d] = true;
                }
        return dp[m - 1][n - 1][B];
    }
}

